namespace RunnersZ.Logic { public sealed class MessageRound { public int Score{get;private set;} public bool Completed{get;private set;} public int HintsUsed{get;private set;} public bool Submit(string answer,string expected){if(string.IsNullOrWhiteSpace(answer))return false;if(!AnswerValidator.IsCorrect(answer,expected))return false;Score+=100;Completed=true;return true;} public string Hint(string expected){if(HintsUsed>=expected.Split(' ').Length)return "";HintsUsed++;Score=System.Math.Max(0,Score-50);var a=expected.Split(' ');return string.Join(" ",a,0,HintsUsed);}}}